text:
 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom, my name is Lucy. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hi Lucy, I'm calling because my latest bill is way higher than it should be. I'm really frustrated with these constant overcharges.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am sorry to hear that you are experiencing issues with your billing. I can certainly look into this for you. Before we proceed, could you please provide your account number?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Sure, it is 10240379. My name is Aisha Khan.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you, Ms. Khan. I see your account for the address 150 Station Road. I understand how upsetting it is to see an unexpected charge on your statement.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "customer",
      "text": "It is. I've been a customer for years and this is the third time this has happened. My phone number is 98870 94397.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I can check if a credit is possible for the overcharge. Please be aware that any refund or credit is subject to approval and typically takes 7-10 business days to process.",
      "tags": [
        "disclosure"
      ]
    },
    {
      "speaker": "customer",
      "text": "Wait, why is it subject to approval? I was overcharged! I want my money back now, not in ten days.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I understand your frustration, but this is the standard procedure for all billing adjustments.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "This is ridiculous. I am tired of dealing with this every few months. I'm just going to cancel my service and switch to another provider.",
      "tags": [
        "churn_signal"
      ]
    },
    {
      "speaker": "agent",
      "text": "I would hate to see you leave. Let me see if I can find a better plan for you.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "I don't want a new plan, I want my money back and a guarantee that this won't happen again!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I cannot guarantee that billing errors will not occur in the future, but I will submit a request for the credit.",
      "tags": [
        "action:submit_credit_request"
      ]
    }
  ]
}
